# Encodes a text for HTML (the test page).
function Get-HtmlText([string]$Text) { return [System.Net.WebUtility]::HtmlEncode($Text) }

<#
.SYNOPSIS
  Writes the test page: one big link per thing to open. Colors and font as the RADE window.
.DESCRIPTION
  The page holds the site address, so it stays in the T21 folder on this computer; it is never a result file.
.PARAMETER Dir
  The T21 folder.
.PARAMETER Site
  The site address.
.OUTPUTS
  System.Int32. The number of links on the page.
#>
function Write-LinksPage([string]$Dir, [string]$Site) {
  $s = $Site.TrimEnd('/')
  $links = @(
    @('Open the new row form', ($s + '/Lists/' + $ListFolder + '/NewForm.aspx'), 'Tests T4 and the list form look: the form other people use.'),
    @('Open the probe list', ($s + '/Lists/' + $ListFolder + '/AllItems.aspx'), 'The rows the tests wrote.'),
    @('Open the list with the button', ($s + '/Lists/' + $ListFolder + '/' + $ViewTitle + '.aspx'), 'The view look: a button that starts a flow.'),
    @('Open the fake workbook', ($s + '/' + $LibFolder + '/' + $BookName + '?web=1'), 'The Excel look: a workbook in Excel for the web.'))
  $body = New-Object System.Text.StringBuilder
  [void]$body.Append('<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><title>90-161.Z test page r6</title><style>')
  [void]$body.Append('body{font-family:"Segoe UI",Arial,sans-serif;color:#1b2430;background:#fff;margin:0}.light{height:6px;background:#ffd520}')
  [void]$body.Append('main{max-width:760px;padding:24px 32px}h1{font-family:"Segoe UI Semibold","Segoe UI",Arial,sans-serif;font-weight:600;')
  [void]$body.Append('font-size:29px;color:#0b2545;margin:8px 0 4px}')
  [void]$body.Append('p{font-size:15px;color:#5a6573;margin:0 0 24px}a.go{display:block;border:1px solid #00539f;background:#00539f;color:#fff;')
  [void]$body.Append('text-decoration:none;font-size:17px;font-weight:700;padding:14px 18px;margin:0 0 4px}')
  [void]$body.Append('a.go:focus{outline:2px solid #0b2545;outline-offset:2px}span.why{display:block;font-size:14px;color:#5a6573;margin:0 0 20px}')
  [void]$body.Append('</style></head><body><div class="light"></div><main>')
  [void]$body.Append('<h1>90-161.Z test page</h1><p>Round R30. Fake data only. Open each link when the RADE window says so.</p>')
  foreach ($l in $links) {
    [void]$body.Append('<a class="go" href="' + (Get-HtmlText $l[1]) + '">' + (Get-HtmlText $l[0]) + '</a><span class="why">' + (Get-HtmlText $l[2]) + '</span>')
  }
  [void]$body.Append('</main></body></html>')
  Set-Content -LiteralPath (Join-Path $Dir $LinksName) -Value $body.ToString() -Encoding UTF8
  return $links.Count
}

<#
.SYNOPSIS
  Make, step m3: the 4 text columns of the probe list (internal name = display name). Adds an ITEM line.
.PARAMETER List
  The probe list (from Find-ByFolder).
.PARAMETER Made
  The counts of what was made (columns is raised here).
.PARAMETER Skip
  The counts of what was there already (columns is raised here).
#>
function Add-ProbeColumn($List, [hashtable]$Made, [hashtable]$Skip) {
  $want = @(@{ Name = 'ProbeTest'; Type = 'Text' }, @{ Name = 'ProbeWay'; Type = 'Text' }, @{ Name = 'ProbeResult'; Type = 'Text' },
    @{ Name = 'ProbeDetail'; Type = 'Note' })
  $have = @(Get-RestValue ("_api/web/lists(guid'" + $List.Id + "')/fields?" + '$select=InternalName&$top=2000') | ForEach-Object { [string]$_.InternalName })
  $bad = 0
  foreach ($c in $want) {
    if ($have -contains $c.Name) { $Skip.columns++; continue }
    $extra = $(if ($c.Type -eq 'Note') { ' RichText="FALSE" NumLines="6"' } else { '' })
    $xml = '<Field Name="' + $c.Name + '" StaticName="' + $c.Name + '" DisplayName="' + $c.Name + '" Required="FALSE" Type="' + $c.Type + '"' + $extra + '></Field>'
    $body = @{ parameters = @{ __metadata = @{ type = 'SP.XmlSchemaFieldCreationInformation' }; SchemaXml = $xml; Options = 24 } } | ConvertTo-Json -Depth 20 -Compress
    try { $null = Invoke-Rest 'Post' ("_api/web/lists(guid'" + $List.Id + "')/fields/createfieldasxml") $body; $Made.columns++ } catch { $bad++ }
  }
  Add-Item 'm3-columns' $(if ($bad -eq 0) { 'PASS' } else { 'FAIL' }) ('columns made=' + $Made.columns + ' already there=' + $Skip.columns + ' refused=' + $bad)
}

<#
.SYNOPSIS
  Make, step m4: the list's own permissions: the site's copied, then Contribute for the associated Visitors group on this
  list only. Adds an ITEM line (and a NOTE when the site has no Visitors group).
.PARAMETER Made
  The counts of what was made (permissions is raised for each change).
#>
function Grant-ProbePermission([hashtable]$Made) {
  $lst = Find-ByFolder $ListFolder
  $lbase = "_api/web/lists(guid'" + $lst.Id + "')"
  if (-not $lst.HasUniqueRoleAssignments) {
    $null = Invoke-Rest 'Post' ($lbase + '/breakroleinheritance(copyRoleAssignments=true,clearSubscopes=true)') '{}'
    $Made.permissions++
  }
  $visitorId = Get-VisitorGroupId
  if ($visitorId -le 0) {
    $script:lines.Add('NOTE m4: no associated Visitors group on this site, so Contribute was not added; the T4 test needs a Visitors group')
    Add-Item 'm4-permissions' 'PASS' ('own permissions on the list (copied now=' + $Made.permissions + '); Visitors group not found')
    return
  }
  $contribute = 0
  try { $contribute = [int](Get-RestValue '_api/web/roledefinitions?$filter=RoleTypeKind%20eq%203&$select=Id')[0].Id } catch { $contribute = 0 }
  if ($contribute -le 0) { throw 'ROLE Contribute not found on the site.' }
  $has = $false
  $bindings = $lbase + '/roleassignments/getbyprincipalid(' + $visitorId + ')/roledefinitionbindings?$select=Id'
  try { $has = @(Get-RestValue $bindings | Where-Object { [int]$_.Id -eq $contribute }).Count -gt 0 } catch { $has = $false }
  if (-not $has) {
    $null = Invoke-Rest 'Post' ($lbase + '/roleassignments/addroleassignment(principalid=' + $visitorId + ',roledefid=' + $contribute + ')') '{}'
    $Made.permissions++
  }
  Add-Item 'm4-permissions' 'PASS' ('own permissions on the list, Visitors group has Contribute (changes now=' + $Made.permissions + ')')
}

<#
.SYNOPSIS
  Make, step m5: saves the fake workbook from the text block in this module (the repo holds no .xlsx: the personal-data
  scan cannot read a binary file), then uploads it. No macro workbook (PFM 17 Nov 26: endpoint security risk).
.PARAMETER Library
  The probe library (from Find-ByFolder).
.PARAMETER Made
  The counts of what was made (files is raised for an upload).
.PARAMETER Skip
  The counts of what was there already (files is raised when the workbook is in the library).
#>
function Send-FakeWorkbook($Library, [hashtable]$Made, [hashtable]$Skip) {
  $wrote = 0
  foreach ($w in @(, @($BookName, $FakeBookBase64))) {
    $bytes = [Convert]::FromBase64String((([string]$w[1] -split '\s+') -join ''))
    $path = Join-Path $script:dir $w[0]
    $same = $false
    if (Test-Path -LiteralPath $path -PathType Leaf) {
      $cur = [IO.File]::ReadAllBytes($path)
      $same = ($cur.Length -eq $bytes.Length) -and ([Convert]::ToBase64String($cur) -eq [Convert]::ToBase64String($bytes))
    }
    if (-not $same) { [IO.File]::WriteAllBytes($path, $bytes); $wrote++ }
  }
  $script:lines.Add('ITEM m5a-workbooks INFO fake workbook saved to the T21 folder now=' + $wrote)
  $filesUri = "_api/web/lists(guid'" + $Library.Id + "')/rootfolder/files?" + '$select=Name&$top=500'
  $inLib = @(Get-RestValue $filesUri | ForEach-Object { [string]$_.Name })
  foreach ($n in @($BookName)) {
    if ($inLib -contains $n) { $Skip.files++; continue }
    $null = Add-PnPFile -Path (Join-Path $script:dir $n) -Folder $LibFolder -ErrorAction Stop
    $Made.files++
  }
  $inLib = @(Get-RestValue $filesUri | ForEach-Object { [string]$_.Name })
  $ok = ($inLib -contains $BookName)
  Add-Item 'm5-files' $(if ($ok) { 'PASS' } else { 'FAIL' }) ('files in the library: the workbook there=' + $(if ($ok) { 'yes' } else { 'no' }) + ' (uploaded now=' + $Made.files + ')')
}

<#
.SYNOPSIS
  The part Make: the library and the list (m1, m2; the same cmdlet T16 uses for its library), the columns, the
  permissions, the workbook and the test page (m3 to m6), then the MADE and SKIPPED count lines. A second run changes
  nothing on the site.
#>
function Invoke-MakePart {
  $made = @{ library = 0; list = 0; columns = 0; permissions = 0; files = 0 }
  $skip = @{ library = 0; list = 0; columns = 0; permissions = 0; files = 0 }
  Write-Now 'Looking for the library and the list'
  $lib = Find-ByFolder $LibFolder
  if ($lib) { $skip.library++ } else {
    Write-Now ('Making the library ' + $LibTitle)
    $null = New-PnPList -Title $LibTitle -Template DocumentLibrary -Url $LibFolder -ErrorAction Stop
    $made.library++; $lib = Find-ByFolder $LibFolder
  }
  Add-Item 'm1-library' $(if ($lib) { 'PASS' } else { 'FAIL' }) $(if ($lib) { 'library there (made=' + $made.library + ')' } else { 'library not on the site after the create step' })
  $lst = Find-ByFolder $ListFolder
  if ($lst) { $skip.list++ } else {
    Write-Now ('Making the list ' + $ListTitle)
    $null = New-PnPList -Title $ListTitle -Template GenericList -Url ('Lists/' + $ListFolder) -ErrorAction Stop
    $made.list++; $lst = Find-ByFolder $ListFolder
  }
  Add-Item 'm2-list' $(if ($lst) { 'PASS' } else { 'FAIL' }) $(if ($lst) { 'list there (made=' + $made.list + ')' } else { 'list not on the site after the create step' })
  if (-not $lib -or -not $lst) { throw 'LIST or library missing after the create step; nothing more was done.' }
  Write-Now 'Adding the 4 columns of the list'
  Add-ProbeColumn $lst $made $skip
  Write-Now 'Setting the permissions of the list'
  Grant-ProbePermission $made
  Write-Now 'Saving and uploading the fake workbook'
  Send-FakeWorkbook $lib $made $skip
  # m6: the test page (it holds the site address: it stays in the T21 folder).
  $n = Write-LinksPage $script:dir $script:site
  Add-Item 'm6-page' 'PASS' ('test page in the T21 folder, links=' + $n)
  $script:lines.Add('MADE library=' + $made.library + ' list=' + $made.list + ' columns=' + $made.columns + ' permission changes=' + $made.permissions + ' files=' + $made.files)
  $script:lines.Add('SKIPPED (already there) library=' + $skip.library + ' list=' + $skip.list + ' columns=' + $skip.columns + ' files=' + $skip.files)
}

# The part Open (no sign-in): writes the test page again and opens it in the browser.
function Invoke-OpenPart {
  Write-Now 'Writing the test page'
  $n = Write-LinksPage $script:dir $script:site
  Add-Item 'o1-page' 'PASS' ('test page written, links=' + $n)
  if (-not $NoLaunch) { Write-Now 'Opening the test page in the browser'; Start-Process -FilePath (Join-Path $script:dir $LinksName) }
  Add-Item 'o2-open' 'PASS' ('test page opened in the browser=' + $(if ($NoLaunch) { 'no (test run)' } else { 'yes' }))
}
'@ }
# ---- File 15 of 21: T21\90161Z-T21-person-r11.ps1 (from scripts/gov/90161Z-T21-person-r11.ps1, sha256 e09ae95b2108)
$files += @{ Dir = 'T21'; Name = '90161Z-T21-person-r11.ps1'; Kind = 'text'; Sha = 'e09ae95b2108'; Data = @'
<#
.SYNOPSIS
  90-161.Z Task 21 probe r11, module "person": the parts Person (the second person for test T4), Ask (the round asks that
  person for a new row, R36) and Clean (removes the person, the list and the library again).
.DESCRIPTION
  Loaded by 90161Z-T21-probe-r11.ps1 (dot-sourced from the same folder); it does nothing when it is run alone.
  Inputs: the values the main file sets ($site, $dir, $StateName, $ListTitle, $ListFolder, $LibTitle, $LibFolder,
  $TestDir, $NoLaunch) and the helpers of the module "common". Outputs: result lines through Add-Item.
  The second person's e-mail address is read in a small window and used in memory only: it is never written to a file,
  a result line or an output stream (tests/ps/Test-T21.ps1 checks this text).
  Network: the one SharePoint site of the main file, through the PnP.PowerShell connection.
  Writes: Person: adds one person to the site's Visitors group; on this computer the state file (3 numbers or flags) and
          the clipboard (the new row form link). Ask: the line T4Asked=yes in that state file and the clipboard (the new
          row form link); nothing on the site. Clean: removes that person from Visitors and PFM Office again, moves the probe list
          and library to the site Recycle Bin, deletes the state file.
  Credentials: none of its own (the main file signs in); no password is asked for.
  Run: not alone; powershell.exe -File 90161Z-T21-probe-r11.ps1 -Part Person (or Ask, or Clean) loads it.
#>

function Read-PersonAddress {
  # The second person's address, typed by the PFM in a small window. It is returned to the caller and used in memory only; this
  # function writes nothing. In a test run (-TestDir) a fake address may come from the test.
  if ($TestDir -and $env:T21_TEST_ADDRESS) { return ([string]$env:T21_TEST_ADDRESS).Trim() }
  $prompt = 'Type the e-mail address of the second person for test T4 (a person who is not you), then select OK. It is used once, stays on this computer and is not saved or sent.'
  try {
    Add-Type -AssemblyName Microsoft.VisualBasic -ErrorAction Stop
    return ([string][Microsoft.VisualBasic.Interaction]::InputBox($prompt, '90-161.Z test T4', '')).Trim()
  } catch {
    if ($env:RADE_CONTRACT) { throw 'ADDRESS window not available: the window for the second person could not open on this computer.' }
    return ([string](Read-Host 'E-mail address of the second person (it is not saved), then press Enter')).Trim()
  }
}

<#
.SYNOPSIS
  Person, step p3: puts the found person into the Visitors group, unless the person is a member already. The numbers are
  saved in the state file before the change, so Clean can find the person even if this part stops half way.
.DESCRIPTION
  A state file from an earlier run of this part that added a person is kept (review, 17 Nov 26): a second run must not
  turn "added by this test" into "was a member before", or Clean would leave the person in Visitors.
.PARAMETER VisitorId
  The Id of the site's Visitors group.
.PARAMETER UserId
  The site user number of the person.
.PARAMETER LoginName
  The person's login name for Add-PnPGroupMember (used in memory only).
.OUTPUTS
  System.Collections.Hashtable. State ('yes', 'was', 'no' or 'other') and Why (the status text, no identity).
#>
function Add-VisitorMember([int]$VisitorId, [int]$UserId, [string]$LoginName) {
  $state = 'no'; $why = ''
  $was = (Get-GroupMemberId $VisitorId) -contains $UserId
  $old = Read-State $script:dir
  $keep = ($old -and $old['WasMember'] -eq 'no')
  if ($keep -and [int]$old['UserId'] -ne $UserId) {
    $state = 'other'; $why = 'a person added by an earlier run is still on file: run the Clean part first, then this part again'
  } else {
    if ($keep) { $was = $false }
    else {
      $stateLines = @(('UserId=' + $UserId), ('GroupId=' + $VisitorId), ('WasMember=' + $(if ($was) { 'yes' } else { 'no' })))
      Set-Content -LiteralPath (Join-Path $script:dir $StateName) -Value $stateLines -Encoding ASCII
    }
  }
  if ($state -eq 'other') { $null = $state }
  elseif ($was) { $state = 'was'; $why = 'the person was already a member and stays one' }
  elseif ($keep -and ((Get-GroupMemberId $VisitorId) -contains $UserId)) { $state = 'yes'; $why = 'added by an earlier run of this part; Clean removes the person' }
  else {
    try {
      $null = Add-PnPGroupMember -LoginName $LoginName -Group $VisitorId -ErrorAction Stop
      if ((Get-GroupMemberId $VisitorId) -contains $UserId) { $state = 'yes' } else { $why = 'the group does not list the person after the add' }
    } catch { $why = 'the add was refused: ' + (Format-Detail ([string]$_.Exception.Message)) }
  }
  return @{ State = $state; Why = $why }
}

<#
.SYNOPSIS
  Person, steps p2 and p3: asks for the address, finds the person on the site and adds the person to Visitors. The
  address is read into one variable, used in the next calls and cleared; it is never written, printed or saved.
.PARAMETER VisitorId
  The Id of the site's Visitors group.
.OUTPUTS
  System.Collections.Hashtable. State ('yes', 'was', 'no' or 'other') and Why (the status text, no identity).
#>
function Add-SecondPerson([int]$VisitorId) {
  $result = @{ State = 'no'; Why = '' }
  Write-Now 'Asking for the address of the second person in a small window'
  $personAddr = Read-PersonAddress
  $addrOk = ($personAddr -match '^[^@\s]+@[^@\s]+\.[^@\s]+$')
  if (-not $addrOk) { Add-Item 'p2-person' 'FAIL' 'no valid address was given in the window'; $result.Why = 'no valid address was given' }
  else {
    $userId = 0; $loginName = ''
    Write-Now 'Looking for the second person on the site'
    try {
      $raw = Invoke-Rest 'Post' '_api/web/ensureuser' (@{ logonName = ('i:0#.f|membership|' + $personAddr) } | ConvertTo-Json -Compress)
      if ($raw -match '"Id"\s*:\s*(\d+)') { $userId = [int]$Matches[1] }
      if ($raw -match '"LoginName"\s*:\s*"([^"]+)"') { $loginName = $Matches[1] }
    } catch { $userId = 0 }
    if ($userId -le 0) {
      try {
        $raw = Invoke-Rest 'Get' ("_api/web/siteusers/getbyemail('" + [uri]::EscapeDataString($personAddr) + "')?" + '$select=Id,LoginName') ''
        if ($raw -match '"Id"\s*:\s*(\d+)') { $userId = [int]$Matches[1] }
        if ($raw -match '"LoginName"\s*:\s*"([^"]+)"') { $loginName = $Matches[1] }
      } catch { $userId = 0 }
    }
    if (-not $loginName) { $loginName = 'i:0#.f|membership|' + $personAddr }
    if ($userId -le 0) { Add-Item 'p2-person' 'FAIL' 'the person was not found on this site'; $result.Why = 'the person was not found on this site' }
    else {
      Add-Item 'p2-person' 'PASS' 'the person was found on this site (the site user number is saved in the state file, no address and no name)'
      Write-Now 'Adding the second person to the Visitors group'
      $result = Add-VisitorMember $VisitorId $userId $loginName
      $isIn = ($result.State -eq 'yes' -or $result.State -eq 'was')
      $inText = $(if ($result.State -eq 'no' -or $result.State -eq 'other') { 'no' } else { 'yes' })
      Add-Item 'p3-visitors' $(if ($isIn) { 'PASS' } else { 'FAIL' }) ('person in the Visitors group=' + $inText + $(if ($result.Why) { ' (' + $result.Why + ')' } else { '' }))
    }
  }
  $personAddr = $null; $loginName = $null; $raw = $null
  return $result
}

<#
.SYNOPSIS
  The part Person (T4 retry, PFM 17 Nov 26): the second person is added to the Visitors group with your sign-in, and
  removed again by Clean. Prints "added to Visitors: yes" or "no" and a status, never who; puts the form link on the
  clipboard.
#>
function Invoke-PersonPart {
  Write-Now 'Looking for the probe list and the Visitors group'
  $lst = Find-ByFolder $ListFolder
  if (-not $lst) { throw 'LIST not found: run -Part Make first.' }
  $visitorId = Get-VisitorGroupId
  $result = @{ State = 'no'; Why = '' }
  if ($visitorId -le 0) { Add-Item 'p1-group' 'FAIL' 'the site has no Visitors group'; $result.Why = 'the site has no Visitors group' }
  else {
    Add-Item 'p1-group' 'PASS' 'the site has a Visitors group'
    $result = Add-SecondPerson $visitorId
  }
  $state = $result.State
  $status = $(if ($state -eq 'yes') { 'added and listed in the group' } elseif ($state -eq 'was') { 'already a member (Clean leaves the person in the group)' } else { $result.Why })
  $script:lines.Add('VISITORS added to Visitors: ' + $(if ($state -eq 'yes') { 'yes' } else { 'no' }) + '; status: ' + $status)
  $clip = 'no'
  if ($NoLaunch) { $clip = 'no (test run)' } else {
    try { Set-Clipboard -Value ($script:site.TrimEnd('/') + '/Lists/' + $ListFolder + '/NewForm.aspx'); $clip = 'yes' } catch { $clip = 'no' }
  }
  $script:lines.Add('ITEM p4-link INFO the link of the new row form is on the clipboard=' + $clip)
}

<#
.SYNOPSIS
  The part Ask (R36; on this computer only, no sign-in): the round asks the second person to add one new row titled T4a
  through the new row form. Writes T4Asked=yes into the state file of Person (the other lines stay), so Read counts T4
  even when no row came (R35: T4 read FAIL when no step had asked), and puts the link of the new row form on the
  clipboard. With no second person on file it writes nothing and fails.
#>
function Invoke-AskPart {
  Write-Now 'Reading the state file of the second person'
  $st = Read-State $script:dir
  if (-not $st) { Add-Item 'k1-asked' 'FAIL' 'no second person on file: run the part Person first'; return }
  $f = Join-Path $script:dir $StateName
  $keep = @(Get-Content -LiteralPath $f | Where-Object { [string]$_ -notmatch '^T4Asked=' })
  Set-Content -LiteralPath $f -Value (@($keep) + 'T4Asked=yes') -Encoding ASCII
  $ok = ((Read-State $script:dir)['T4Asked'] -eq 'yes')
  Add-Item 'k1-asked' $(if ($ok) { 'PASS' } else { 'FAIL' }) ('T4Asked=yes in the state file (Read now counts T4)=' + $(if ($ok) { 'yes' } else { 'no' }))
  $clip = 'no'
  if ($NoLaunch) { $clip = 'no (test run)' } else {
    try { Set-Clipboard -Value ($script:site.TrimEnd('/') + '/Lists/' + $ListFolder + '/NewForm.aspx'); $clip = 'yes' } catch { $clip = 'no' }
  }
  $script:lines.Add('ITEM k2-link INFO the link of the new row form is on the clipboard=' + $clip)
}

<#
.SYNOPSIS
  Clean, step c1: removes the second person from the Visitors group again (found by the saved numbers in the state file),
  then deletes the state file. A person who was a member before the test stays. Adds one ITEM line.
#>
function Clear-SecondPerson {
  $state = Read-State $script:dir
  if (-not $state) { Add-Item 'c1-person' 'PASS' 'no second person on file (nothing to remove)'; return }
  if ($state['WasMember'] -eq 'yes') {
    Add-Item 'c1-person' 'PASS' 'the second person was a Visitors member before the test, so the person stays (state file deleted)'
    try { Remove-Item -LiteralPath (Join-Path $script:dir $StateName) -ErrorAction Stop } catch { $null = $_ }
    return
  }
  Write-Now 'Removing the second person from the Visitors group'
  try {
    $uid = [int]$state['UserId']; $gid = 0
    if ($state['GroupId'] -match '^\d+$') { $gid = [int]$state['GroupId'] }
    if ($gid -le 0) { $gid = [int]((Invoke-Rest 'Get' '_api/web/associatedvisitorgroup?$select=Id' '') | ConvertFrom-Json).Id }
    $members = Get-GroupMemberId $gid
    if ($members -contains $uid) {
      $null = Invoke-Rest 'Post' ('_api/web/sitegroups/getbyid(' + $gid + ')/users/removebyid(' + $uid + ')') '{}'
      $members = Get-GroupMemberId $gid
    }
    $still = $members -contains $uid
    $text = $(if (-not $still) { 'the second person is not in the Visitors group (state file deleted)' } else { 'the second person is still in the Visitors group (state file kept; run Clean again)' })
    Add-Item 'c1-person' $(if (-not $still) { 'PASS' } else { 'FAIL' }) $text
    if (-not $still) { Remove-Item -LiteralPath (Join-Path $script:dir $StateName) -ErrorAction Stop }
  } catch { Add-Item 'c1-person' 'FAIL' ('the second person could not be removed: ' + (Format-Detail ([string]$_.Exception.Message)) + ' (state file kept; run Clean again)') }
}

<#
.SYNOPSIS
  The part Clean: runs each step on its own, even if an earlier one failed. First the person (Visitors, then PFM Office:
  module "office"), then the two objects (found
  by their folder name), to the site Recycle Bin (restorable for 93 days). The probe flows stay in the solution.
#>
function Invoke-CleanPart {
  Write-Now 'Looking for a second person on file'
  Clear-SecondPerson
  Clear-OfficeMember
  foreach ($o in @(@('c2-list', $ListTitle, $ListFolder), @('c3-library', $LibTitle, $LibFolder))) {
    try {
      $x = Find-ByFolder $o[2]
      if (-not $x) { Add-Item $o[0] 'PASS' ('"' + $o[1] + '" was not on the site (nothing to remove)'); continue }
      Write-Now ('Moving ' + $o[1] + ' to the site Recycle Bin')
      # R29a finding 7: the command returns the Recycle Bin item ID; it is not shown (it reached the log as a raw table).
      $null = Remove-PnPList -Identity ([string]$x.Id) -Recycle -Force -ErrorAction Stop
      $still = Find-ByFolder $o[2]
      $text = $(if (-not $still) { 'moved to the site Recycle Bin (restorable for 93 days)' } else { 'is still on the site' })
      Add-Item $o[0] $(if (-not $still) { 'PASS' } else { 'FAIL' }) ('"' + $o[1] + '" ' + $text)
    } catch { Add-Item $o[0] 'FAIL' ('"' + $o[1] + '" could not be removed: ' + (Format-Detail ([string]$_.Exception.Message)) + ' (run Clean again)') }
  }
  $flows = '"90161Z T21 Probe Health r6" and "90161Z T21 Probe Button r6"'
  $script:lines.Add('NOTE the probe flows ' + $flows + ' are flows of the solution "90-161.Z flows"; this script does not touch flows or solutions')
}
'@ }
# ---- File 16 of 21: T21\90161Z-T21-look-r11.ps1 (from scripts/gov/90161Z-T21-look-r11.ps1, sha256 90d718d40afe)
$files += @{ Dir = 'T21'; Name = '90161Z-T21-look-r11.ps1'; Kind = 'text'; Sha = '90d718d40afe'; Data = @'
<#
.SYNOPSIS
  90-161.Z Task 21 probe r11, module "look": the parts Form (a header on the list form) and View (a list view with a
  button that starts the button flow "90161Z T21 Probe Button r6" of the solution "90-161.Z flows"). The part Look runs
  both.
.DESCRIPTION
  Loaded by 90161Z-T21-probe-r11.ps1 (dot-sourced from the same folder); it does nothing when it is run alone.
  Inputs: the values the main file sets ($ListTitle, $ListFolder, $ViewTitle, $HeaderText) and the helpers of the module
  "common"; View takes the button flow's ID from the button-flow-id block below, which scripts/build_flow_solution.py
  writes at build time (the flow's workflow ID in the solution, the same on every build; R34: no export file). Outputs:
  result lines through Add-Item and Add-Test (FORM, VIEW).
  R29a finding 6: the round skipped the look at the form because one step held both tests and the view failed. With Form
  and View as separate parts, the round can run the look at the form after Form alone.
  Network: the one SharePoint site of the main file, through the PnP.PowerShell connection (CSOM, then REST).
  Writes: Form: the form formatting (ClientFormCustomFormatter) of the probe list's content type. View: the view
          "ProbeButton" on the probe list and its formatting (CustomFormatter). Nothing on this computer.
  Credentials: none of its own (the main file signs in).
  Run: not alone; powershell.exe -File 90161Z-T21-probe-r11.ps1 -Part Form, View or Look loads it.
#>

# >>> button-flow-id: generated from flow/solution/defs/90161Z-T21-probe-button-r6.json by scripts/build_flow_solution.py (do not edit)
$ButtonFlowId = 'ce93ba66-4985-5431-bec3-5f371af52372'
# <<< button-flow-id

<#
.SYNOPSIS
  Sets a formatting JSON on a content type (form header) or a view. Easy path first: the CSOM property; then the REST
  merge.
.PARAMETER Kind
  'form' (content type) or 'view'.
.PARAMETER Json
  The formatting JSON text.
.PARAMETER ListId
  The probe list's Id.
.PARAMETER TargetId
  The content type Id (form) or the view Id (view).
.OUTPUTS
  System.String. 'csom', 'rest' or 'none'; the last error text is kept in $script:fmtError.
#>
function Send-Formatter([string]$Kind, [string]$Json, [string]$ListId, [string]$TargetId) {
  $script:fmtError = ''
  try {
    $ctx = Get-PnPContext
    $list = $ctx.Web.Lists.GetById([guid]$ListId)
    if ($Kind -eq 'form') { $t = $list.ContentTypes.GetById($TargetId); $t.ClientFormCustomFormatter = $Json; $t.Update($false) }
    else { $t = $list.Views.GetById([guid]$TargetId); $t.CustomFormatter = $Json; $t.Update() }
    $ctx.ExecuteQuery()
    return 'csom'
  } catch { $script:fmtError = [string]$_.Exception.Message }
  try {
    $lbase = "_api/web/lists(guid'" + $ListId + "')"
    if ($Kind -eq 'form') {
      $body = @{ __metadata = @{ type = 'SP.ContentType' }; ClientFormCustomFormatter = $Json } | ConvertTo-Json -Depth 5 -Compress
      $null = Invoke-Rest 'Merge' ($lbase + "/contenttypes('" + $TargetId + "')") $body
    } else {
      $body = @{ __metadata = @{ type = 'SP.View' }; CustomFormatter = $Json } | ConvertTo-Json -Depth 5 -Compress
      $null = Invoke-Rest 'Merge' ($lbase + "/views(guid'" + $TargetId + "')") $body
    }
    return 'rest'
  } catch { $script:fmtError = [string]$_.Exception.Message }
  return 'none'
}

# Finds the probe list or stops the part (Form and View need it).
function Get-ProbeListOrStop {
  Write-Now 'Looking for the probe list'
  $lst = Find-ByFolder $ListFolder
  if (-not $lst) { throw 'LIST not found: run -Part Make first.' }
  return $lst
}

<#
.SYNOPSIS
  The part Form (a): the header of the list form (the form formatting of the content type), read back from the content
  type. Adds the ITEM line l1-form and the test FORM.
#>
function Invoke-FormPart {
  $lst = Get-ProbeListOrStop
  $lbase = "_api/web/lists(guid'" + $lst.Id + "')"
  $ctId = ''
  try { $cts = @(Get-RestValue ($lbase + '/contenttypes?$select=Id,Name')); if ($cts.Count) { $ctId = [string]$cts[0].Id.StringValue } } catch { $ctId = '' }
  $formPass = $false; $route = 'none'; $readBack = 'no'
  if (-not $ctId) { Add-Item 'l1-form' 'FAIL' 'no content type found on the list' }
  else {
    $hdr = [ordered]@{ headerJSONFormatter = [ordered]@{ elmType = 'div'; style = [ordered]@{ padding = '12px'; 'font-size' = '18px'; 'font-weight' = '600' }; txtContent = $HeaderText } }
    Write-Now 'Setting the header on the list form and reading it back'
    $route = Send-Formatter 'form' ($hdr | ConvertTo-Json -Depth 8 -Compress) ([string]$lst.Id) $ctId
    try {
      $raw = Invoke-Rest 'Get' ($lbase + "/contenttypes('" + $ctId + "')?" + '$select=ClientFormCustomFormatter') ''
      if ($raw.Contains($HeaderText)) { $readBack = 'yes' }
    } catch { $readBack = 'not read' }
    $formPass = ($readBack -eq 'yes')
    $why = $(if ($route -eq 'none') { '; ' + (Format-Detail $script:fmtError) } else { '' })
    Add-Item 'l1-form' $(if ($formPass) { 'PASS' } else { 'FAIL' }) ('header formatting set (route=' + $route + ') and read back from the content type=' + $readBack + $why)
  }
  $summary = 'a header on the list form (form formatting set by script)=' + $(if ($formPass) { 'PASS' } else { 'FAIL' }) + ' (route=' + $route + '; read back=' + $readBack + ')'
  Add-Test 'FORM' @($summary + '; what the form shows is left to your answers') $formPass
}

# The button flow's ID from the button-flow-id block (lower case), or '' when the block holds no ID.
function Get-ButtonFlowId {
  $bt = ([string]$ButtonFlowId).Trim()
  if ($bt -match '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$') { return $bt.ToLowerInvariant() }
  return ''
}

<#
.SYNOPSIS
  Makes the view "ProbeButton" when it is missing and returns its Id ('' when it is not there after the create step).
.PARAMETER ListBase
  The REST address of the probe list (_api/web/lists(guid'...')).
.OUTPUTS
  System.Collections.Hashtable. Id (the view Id or '') and Made (1 when the view was made now, else 0).
#>
function Get-ButtonView([string]$ListBase) {
  $viewId = ''
  try { $vs = @(Get-RestValue ($ListBase + '/views?$select=Id,Title') | Where-Object { [string]$_.Title -eq $ViewTitle }); if ($vs.Count) { $viewId = [string]$vs[0].Id } } catch { $viewId = '' }
  $viewMade = 0
  if (-not $viewId) {
    Write-Now ('Making the view ' + $ViewTitle)
    $null = Add-PnPView -List $ListTitle -Title $ViewTitle -Fields @('Title', 'ProbeTest', 'ProbeResult') -ErrorAction Stop
    $viewMade++
    $vs = @(Get-RestValue ($ListBase + '/views?$select=Id,Title') | Where-Object { [string]$_.Title -eq $ViewTitle }); if ($vs.Count) { $viewId = [string]$vs[0].Id }
  }
  return @{ Id = $viewId; Made = $viewMade }
}

<#
.SYNOPSIS
  The part View (b): a view with a button that starts the button flow (customRowAction executeFlow with the ID of the
  flow "90161Z T21 Probe Button r6" from the button-flow-id block), read back from the view. Adds the ITEM line l2-view and
  the test VIEW.
#>
function Invoke-ViewPart {
  $lst = Get-ProbeListOrStop
  $lbase = "_api/web/lists(guid'" + $lst.Id + "')"
  $btnId = Get-ButtonFlowId
  if (-not $btnId) {
    Add-Item 'l2-view' 'FAIL' 'no button flow ID in the look module (its button-flow-id block is empty), so the view was not made'
    Add-Test 'VIEW' @('b a view formatted by script with a button that starts a flow=FAIL (flow ID known to the script=no; the build left no ID)') $false
    return
  }
  $view = Get-ButtonView $lbase
  $viewPass = $false; $vroute = 'none'; $vback = 'no'
  if (-not $view.Id) { Add-Item 'l2-view' 'FAIL' 'the view is not on the list after the create step' }
  else {
    $params = '{"id":"' + $btnId + '","headerText":"Run the test flow","runFlowButtonText":"Run"}'
    $fmt = [ordered]@{ '$schema' = 'https://developer.microsoft.com/json-schemas/sp/view-formatting.schema.json'
      rowFormatter = [ordered]@{ elmType = 'div'; style = [ordered]@{ display = 'flex'; 'align-items' = 'center'; padding = '4px' }
        children = @([ordered]@{ elmType = 'span'; style = [ordered]@{ flex = '1' }; txtContent = '[$Title]' },
          [ordered]@{ elmType = 'button'; txtContent = 'Run the test flow'; customRowAction = [ordered]@{ action = 'executeFlow'; actionParams = $params } }) } }
    Write-Now 'Setting the button on the view and reading it back'
    $vroute = Send-Formatter 'view' ($fmt | ConvertTo-Json -Depth 10 -Compress) ([string]$lst.Id) $view.Id
    try {
      $raw = Invoke-Rest 'Get' ($lbase + "/views(guid'" + $view.Id + "')?" + '$select=CustomFormatter') ''
      if ($raw.Contains('executeFlow') -and $raw.Contains($btnId)) { $vback = 'yes' }
    } catch { $vback = 'not read' }
    $viewPass = ($vback -eq 'yes')
    $why = $(if ($vroute -eq 'none') { '; ' + (Format-Detail $script:fmtError) } else { '' })
    Add-Item 'l2-view' $(if ($viewPass) { 'PASS' } else { 'FAIL' }) ('view made now=' + $view.Made + '; formatting set (route=' + $vroute + ') and read back from the view=' + $vback + $why)
  }
  $summary = 'b a view formatted by script with a button that starts a flow=' + $(if ($viewPass) { 'PASS' } else { 'FAIL' })
  Add-Test 'VIEW' @($summary + ' (route=' + $vroute + '; read back=' + $vback + '; flow ID known to the script=yes); whether the button runs is read by the Read part') $viewPass
}
'@ }
